{
  "name": "@example/kubeclaw-greeting-stage",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test tests/stage.test.mjs"
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": ["prefix"],
  "properties": {
    "prefix": {
      "type": "string",
      "minLength": 1,
      "maxLength": 80
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": ["name"],
  "properties": {
    "name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 80
    },
    "fail": {
      "type": "boolean"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "oneOf": [
    {
      "type": "object",
      "additionalProperties": false,
      "required": ["schemaVersion", "outcome", "artifacts", "facts"],
      "properties": {
        "schemaVersion": { "const": "stage-result.v2" },
        "outcome": { "const": "passed" },
        "artifacts": { "type": "array", "maxItems": 0 },
        "facts": {
          "type": "object",
          "additionalProperties": false,
          "required": ["tutorial.greeting"],
          "properties": {
            "tutorial.greeting": { "type": "string", "minLength": 1, "maxLength": 200 }
          }
        }
      }
    },
    {
      "type": "object",
      "additionalProperties": false,
      "required": ["schemaVersion", "outcome", "reason", "artifacts"],
      "properties": {
        "schemaVersion": { "const": "stage-result.v2" },
        "outcome": { "const": "failed" },
        "reason": {
          "type": "object",
          "additionalProperties": false,
          "required": ["code", "message"],
          "properties": {
            "code": { "const": "tutorial.requested_failure" },
            "message": { "type": "string", "minLength": 1, "maxLength": 200 }
          }
        },
        "artifacts": { "type": "array", "maxItems": 0 }
      }
    }
  ]
}

export async function execute(input, context) {
  if (input.fail === true) {
    return {
      schemaVersion: 'stage-result.v2',
      outcome: 'failed',
      reason: {
        code: 'tutorial.requested_failure',
        message: `The input selects failure for ${input.name}.`,
      },
      artifacts: [],
    };
  }
  return {
    schemaVersion: 'stage-result.v2',
    outcome: 'passed',
    artifacts: [],
    facts: {
      'tutorial.greeting': `${context.contract.config.prefix}, ${input.name}!`,
    },
  };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { execute } from '../src/stage.js';

const context = Object.freeze({
  contract: Object.freeze({ config: Object.freeze({ prefix: 'Hello' }) }),
});

test('returns a decision fact to the caller', async () => {
  assert.deepEqual(await execute({ name: 'KubeClaw' }, context), {
    schemaVersion: 'stage-result.v2',
    outcome: 'passed',
    artifacts: [],
    facts: { 'tutorial.greeting': 'Hello, KubeClaw!' },
  });
});

test('returns an intentional terminal failure', async () => {
  assert.deepEqual(await execute({ name: 'KubeClaw', fail: true }, context), {
    schemaVersion: 'stage-result.v2',
    outcome: 'failed',
    reason: {
      code: 'tutorial.requested_failure',
      message: 'The input selects failure for KubeClaw.',
    },
    artifacts: [],
  });
});

